import numpy as np

def r(x):
    # Rational transform mapping [0,1] -> [0,1] such that r(x) > x for x in (0,1).
    # This ensures the program output (which is increasing in x) increases.
    return (2.0 * x) / (1.0 + x)

def R(y_orig, y_new):
    # Validity check: determinants of positive definite matrices must be finite and positive.
    return np.isfinite(y_orig) and np.isfinite(y_new) and y_orig > 0 and y_new > 0
